    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(bool expectRevert) public {
        require(expectRevert == (msg.sender != c.ceoAddress()));
        bool reverted; c.DrugDealer(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        assert(reverted == expectRevert);
